-- 2. Backup STB_ProdRouteHist
IF OBJECT_ID('dbo.BK_20260821_HY_STB_ProdRouteHist', 'U') IS NOT NULL
    DROP TABLE dbo.BK_20260821_HY_STB_ProdRouteHist;

SELECT PRH.* INTO dbo.BK_20260821_HY_STB_ProdRouteHist
FROM dbo.STB_ProdRouteHist PRH WITH (NOLOCK)
INNER JOIN dbo.STB_SetInfo SI WITH (NOLOCK) ON PRH.ControlNo = SI.ControlNo
